import numpy as np

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = np.array([[int(x) for x in r] for r in rows])

demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

Q1 = demo_out[:8, :8]
Q2 = demo_out[:8, 8:]
Q3 = demo_out[8:, :8]
Q4 = demo_out[8:, 8:]

# Maybe Q2-Q4 come from different rotations/reflections of the INPUT
# Let me generate all possible 8x8 views from the input with various transforms

def transform(grid, op):
    """Apply transformation op to grid"""
    if op == 'identity':
        return grid.copy()
    elif op == 'rotate90cw':
        return np.rot90(grid, k=-1)
    elif op == 'rotate180':
        return np.rot90(grid, k=2)
    elif op == 'rotate270cw':
        return np.rot90(grid, k=1)
    elif op == 'flip_h':
        return grid[:, ::-1]
    elif op == 'flip_v':
        return grid[::-1, :]
    elif op == 'flip_d':  # flip along diagonal (transpose)
        return grid.T
    elif op == 'transpose':
        return grid.T
    return grid.copy()

# Test all combinations
ops = ['identity', 'rotate90cw', 'rotate180', 'rotate270cw', 'flip_h', 'flip_v', 'flip_d']
print("Checking which transform matches each quadrant:")
for qname, qgrid in [("Q1", Q1), ("Q2", Q2), ("Q3", Q3), ("Q4", Q4)]:
    for op in ops:
        result = transform(demo_in, op)
        if np.array_equal(qgrid, result):
            print(f"{qname} matches: {op}")
